def academic_books():
    result=[]
    colors=['#405d69','#52664d','#745c4b','#545b7c']
    for i,row in enumerate(ACADEMIC_BOOKS):
        id,title,author,isbn,pages,year,genre,subject,level,description,tags,url=row
        result.append(dict(id=id,title=title,author=author,isbn=isbn,pages=pages,year=year,genre=genre,subject=subject,mood='Practical',pace='Slow',level=level,color=colors[i%len(colors)],description=description,tags=['academic',subject,*tags],language='eng',featured=False,source='Publisher/library edition record; project-curated description',source_url=url,evidence_label='Academic subjects and prerequisites are project-curated; confirm your course edition'))
    return result
